// CORRECT — import watch from the public @wordpress/interactivity package.
// Requires WordPress 7.0+ (released May 20, 2026).
import { store, watch } from '@wordpress/interactivity';

const { state } = store( 'my-plugin/counter', {
  state: { count: 0 },
} );

// watch() subscribes to every reactive value read inside the callback and
// re-runs the callback whenever any of them change.
watch( () => {
  console.log( 'Count is now', state.count );
} );

entries.bad_pattern:
// WRONG — effect is not exported from @wordpress/interactivity.
// This will throw a module resolution error or import a stale @preact/signals copy.
import { effect } from '@preact/signals';           // direct Preact dep — do not reach inside WP
import { store } from '@wordpress/interactivity';

const { state } = store( 'my-plugin/counter', {
  state: { count: 0 },
} );

// This fires on every signals change but is not the public @wordpress/interactivity API.
effect( () => {
  console.log( 'Count changed to', state.count );
} );

